    "source": "from typing import NamedTuple\n\n\nclass Edge(NamedTuple):\n    u: int\n    v: int\n    w: int\n\n\ndef kruskal(n: int, edges: list[Edge]) -> tuple[int, list[Edge]]:\n    \"\"\"Kruskal MST — complete Python reference (union-find with path compression).\"\"\"\n    parent = list(range(n))\n\n    def find(x: int) -> int:\n        if parent[x] != x:\n            parent[x] = find(parent[x])\n        return parent[x]\n\n    sorted_edges = sorted(edges, key=lambda e: e.w)\n    mst: list[Edge] = []\n    total = 0\n    for e in sorted_edges:\n        a = find(e.u)\n        b = find(e.v)\n        if a == b:\n            continue\n        parent[a] = b\n        mst.append(e)\n        total += e.w\n        if len(mst) == n - 1:\n            break\n    return total, mst\n",
