    "source": "// Kruskal MST — complete C++17 reference (union-find with path compression).\n#include <algorithm>\n#include <functional>\n#include <numeric>\n#include <utility>\n#include <vector>\n\nstruct Edge { int u, v; long long w; };\n\nstd::pair<long long, std::vector<Edge>> kruskal(int n, const std::vector<Edge>& edges) {\n    std::vector<int> parent(n);\n    std::iota(parent.begin(), parent.end(), 0);\n    std::function<int(int)> find = [&](int x) { return parent[x] == x ? x : parent[x] = find(parent[x]); };\n    std::vector<Edge> sorted = edges;\n    std::stable_sort(sorted.begin(), sorted.end(), [](const Edge& a, const Edge& b) { return a.w < b.w; });\n    std::vector<Edge> mst;\n    long long total = 0;\n    for (const Edge& e : sorted) {\n        int a = find(e.u);\n        int b = find(e.v);\n        if (a == b) continue;\n        parent[a] = b;\n        mst.push_back(e);\n        total += e.w;\n        if (static_cast<int>(mst.size()) == n - 1) break;\n    }\n    return {total, mst};\n}\n",
