    "source": "/// Kruskal MST — complete Rust reference (union-find with path compression).\n#[derive(Clone, Copy)]\npub struct Edge {\n    pub u: usize,\n    pub v: usize,\n    pub w: i64,\n}\n\npub fn kruskal(n: usize, edges: &[Edge]) -> (i64, Vec<Edge>) {\n    fn find(parent: &mut Vec<usize>, x: usize) -> usize {\n        if parent[x] != x {\n            let p = parent[x];\n            parent[x] = find(parent, p);\n        }\n        parent[x]\n    }\n    let mut parent: Vec<usize> = (0..n).collect();\n    let mut sorted = edges.to_vec();\n    sorted.sort_by_key(|e| e.w);\n    let mut mst: Vec<Edge> = Vec::new();\n    let mut total = 0;\n    for e in sorted {\n        let a = find(&mut parent, e.u);\n        let b = find(&mut parent, e.v);\n        if a == b {\n            continue;\n        }\n        parent[a] = b;\n        mst.push(e);\n        total += e.w;\n        if mst.len() == n - 1 {\n            break;\n        }\n    }\n    (total, mst)\n}\n",
